"use strict";(globalThis.webpackChunkmy_study_site=globalThis.webpackChunkmy_study_site||[]).push([[9700],{3655(i){i.exports=JSON.parse('{"categoryGeneratedIndex":{"title":"Probability Distributions","description":"A distribution is how probability is spread over the values a random variable can take. This module works one lecture at a time from the ground up: the three functions that describe any distribution (PMF, PDF, CDF), the discrete family (Bernoulli, Binomial, Poisson), the continuous family (Normal, Standard Normal & z-scores, Uniform, Log-Normal), the heavy-tailed family (Power Law, Pareto) that finance actually lives in, and finally the two ideas that connect a sample back to reality \u2014 the Central Limit Theorem and estimation. Every page has an interactive lab or 3D visual and a runnable example. (Study reference: the \'Probability Distribution Functions\' section of a Complete Data Science bootcamp \u2014 all notes, code, and visuals are my own.)","slug":"/Probability/distributions","permalink":"/docs/Probability/distributions","sidebar":"tutorialSidebar","navigation":{"previous":{"title":"Combinatorics","permalink":"/docs/Probability/combinatorics"},"next":{"title":"1. Foundations: PMF, PDF, CDF","permalink":"/docs/category/1-foundations-pmf-pdf-cdf"}}}}')}}]);